const a = $('Rules').first().json;
let r = {};
try { r = a.agent ? ($('Trust agent').first().json || {}) : {}; } catch (e) { r = {}; }
const raw = typeof r.output === 'string' ? r.output : '';
const err = a.agent && r.error ? String(r.error.message || r.error).slice(0, 300) : null;
const calls = a.agent ? toolCalls(r.intermediateSteps) : [];
const chk = a.agent && raw ? checkAgent(raw, a.text, a.rules) : { parsed: false, kept: [], dropped: [], summary: null };
const signals = mergeSignals(a.db_signals, a.rules, chk.kept);
const agentState = !a.agent ? (a.skip_reason || 'off') : err ? 'failed' : !raw ? 'no_answer' : !chk.parsed ? 'unparsed' : 'answered';
const step = { agent: 'A4_trust_agent', prompt_version_id: a.prompt_version_id || null, model: a.model || null,
  input: { chars: Array.from(a.text || '').length, rule_hits: a.rules.map((x) => x.signal), db_signals: a.db_signals.map((x) => x.signal) },
  output: { state: agentState, kept: chk.kept.map((x) => ({ signal: x.signal, from: x.from, points: x.points })),
            dropped: chk.dropped, raw_chars: Array.from(raw).length },
  tool_calls: calls.map((x) => ({ tool: x.tool })), latency_ms: Date.now() - a.t0, tokens_in: null, tokens_out: null,
  error: err || (a.agent && !raw ? 'no_answer' : null) };
return [{ json: { listing_id: a.listing_id, step, payload: { signals, summary: chk.summary,
  prompt_version_id: a.agent ? a.prompt_version_id : null, model: a.agent ? a.model : null,
  agent: { state: agentState, tool_calls: calls.map((x) => x.tool), kept: chk.kept.length, dropped: chk.dropped.length } } } }];

// wf.trust.assess > "Result": what the submit needs (the stored report) and the trace step.
const c = $('Check answer').first().json;
const r = ($input.first().json || {}).r || null;
if (!r || !r.report_id) return [{ json: { ok: false, error_code: 'store_failed', steps: [c.step] } }];
return [{ json: { ok: true, report_id: r.report_id, score: r.score, verdict: r.verdict, hard: r.hard, flags: r.flags,
  signals: (r.signals || []).map((x) => x.signal), agent: r.agent, steps: [c.step] } }];
